const employment = ctx.subject.employment;
const terms = employment.terms;
const rate = get(terms, 'rate', {});
const unit = get(rate, 'unit', 'MONTHLY');
const amount = Number(get(rate, 'amount', 0));
const fixed = Object.entries(get(terms, 'allowances', {})).reduce(
	(total, entry) =>
		get(entry[1], 'variability', 'FIXED') === 'VARIABLE'
			? total
			: total + Number(get(entry[1], 'amount', 0)),
	0
);
if (unit === 'PIECE') return false;
const yearly = ctx.lookup.days_per_week * ctx.lookup.weeks_per_year;
const monthly =
	unit === 'MONTHLY' ? amount + fixed
	: unit === 'DAILY' ? (amount * yearly) / ctx.lookup.months_per_year
	: (amount * ctx.lookup.normal_hours_per_day * yearly) / ctx.lookup.months_per_year;
if (monthly <= ctx.lookup.monthly_wage_threshold) return true;
if (ctx.lookup.manual_categories.includes(get(terms, 'statutory_work_category', ''))) return true;
const facts = get(employment, 'employee_extension_data.term_facts', {});
return get(facts, 'overtime_by_contract', false) === true;

