// js
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'employee_extension_data.term_facts', {});
const rate = get(terms, 'rate', {});
const unit = get(rate, 'unit', 'MONTHLY');
const amount = Number(get(rate, 'amount', 0));
const allowances = ctx.lookup.fixed_allowances_in_ordinary_pay
	? Object.entries(get(terms, 'allowances', {}))
	: [];
const fixed = allowances
	.filter(
		(entry) =>
			get(entry[1], 'variability', 'FIXED') !== 'VARIABLE' &&
			!ctx.lookup.excluded_allowances.includes(entry[0])
	)
	.reduce((total, entry) => total + Number(get(entry[1], 'amount', 0)), 0);
const daily =
	unit === 'MONTHLY' ? (amount + fixed) / ctx.lookup.monthly_divisor
	: unit === 'DAILY' ? amount
	: 0;
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * ctx.lookup.normal_hours_per_day
			: ctx.lookup.normal_hours_per_day
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.normal_hours_per_day)
		)
	: normal;
const tier = Math.max(0, full - normal);
const orpDay = unit === 'HOURLY' ? amount * normal : daily;
const orpHour = unit === 'HOURLY' ? amount : orpDay / normal;
const days = get(ctx, 'work.days', []);
const ordinary = days
	.filter((day) => ['WORK', 'OFF'].includes(get(day, 'day_type', 'WORK')) && !ctx.lookup.holiday_kinds.includes(get(day, 'holiday_kind', 'NONE')))
	.toSorted((a, b) => {
		const left = String(get(a, 'date', ''));
		const right = String(get(b, 'date', ''));
		if (left < right) return -1;
		return left > right ? 1 : 0;
	});
const charged = sum(
	ordinary.map((day) => {
		// all hours on an off day are overtime at the standard premium; a rest day has its own bands
		const hours = Math.max(0, Number(get(day, get(day, 'day_type', 'WORK') === 'OFF' ? 'worked_hours' : 'overtime_hours', 0)));
		return partTime
			? Math.min(hours, tier) * ctx.lookup.part_time_premium +
					Math.max(0, hours - tier) * ctx.lookup.standard_premium
			: hours * ctx.lookup.standard_premium;
	})
);
return charged * orpHour;

