const rate = get(terms, 'rate', {});
const unit = get(rate, 'unit', 'MONTHLY');
const amount = Number(get(rate, 'amount', 0));
const allowances = ctx.lookup.fixed_allowances_in_ordinary_pay
	? Object.entries(get(terms, 'allowances', {}))
	: [];
