	)
	.reduce((total, entry) => total + Number(get(entry[1], 'amount', 0)), 0);
const daily =
	unit === 'MONTHLY' ? (amount + fixed) / ctx.lookup.monthly_divisor
	: unit === 'DAILY' ? amount
	: 0;
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * ctx.lookup.normal_hours_per_day
			: ctx.lookup.normal_hours_per_day
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.normal_hours_per_day)
		)
	: normal;
const tier = Math.max(0, full - normal);
const orpDay = unit === 'HOURLY' ? amount * normal : daily;
const orpHour = unit === 'HOURLY' ? amount : orpDay / normal;
const days = get(ctx, 'work.days', []);
const other = unit === 'DAILY' || unit === 'HOURLY';
const charged = sum(
	days
		.filter((day) => get(day, 'day_type', 'WORK') === 'REST' && !ctx.lookup.holiday_kinds.includes(get(day, 'holiday_kind', 'NONE')))
		.map((day) => {
			const worked = Math.min(Number(get(day, 'worked_hours', 0)), normal);
			if (worked <= 0) return 0;
			if (worked <= normal * ctx.lookup.half_day_hours_factor)
				return other ? ctx.lookup.other_half_day : ctx.lookup.monthly_half_day;
			return other ? ctx.lookup.other_full_day : ctx.lookup.monthly_full_day;
		})
);
return charged * orpDay;

